/** Every file of `templates/starter/site` (GitHub Pages shell), by repo path. */
export const STARTER_SITE_FILES: Readonly<Record<string, string>> = {
  ".github/workflows/publish.yml": "# .github/workflows/publish.yml (generated; managed by site-kit updates)\nname: Publish\non:\n  push: { branches: [main] }\n  workflow_dispatch:\npermissions: { contents: read, pages: write, id-token: write }\nconcurrency: { group: publish, cancel-in-progress: true }\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        # package.json keys the npm cache: Hub-created sites have no lockfile at first.\n        with: { node-version: 24, cache: npm, cache-dependency-path: package.json }\n      - uses: actions/cache@v6\n        with:\n          path: node_modules/.astro\n          key: os-assets-${{ hashFiles('media/**') }}\n          restore-keys: os-assets-\n      # Sites created by the Hub start without a lockfile.\n      - run: if [ -f package-lock.json ]; then npm ci; else npm install; fi\n      - run: npx openspace check --ci # schema, links, budgets, secret scan\n      - run: npm run build # astro build (+ pagefind, og images)\n        env:\n          OPENSPACE_TURNSTILE_SITE_KEY: ${{ vars.OPENSPACE_TURNSTILE_SITE_KEY }}\n          # Self-host the font pairing (downloaded once from Google Fonts during the build).\n          OPENSPACE_GOOGLE_FONTS: download\n          OPENSPACE_REMOTE_IMAGES: download\n      - uses: actions/upload-pages-artifact@v5\n        with: { path: dist }\n  deploy:\n    needs: build\n    runs-on: ubuntu-latest\n    environment: { name: github-pages, url: \"${{ steps.d.outputs.page_url }}\" }\n    steps:\n      - id: d\n        uses: actions/deploy-pages@v5\n",
  ".gitignore": "node_modules/\ndist/\n.astro/\n.wrangler/\n.env\n.env.*\n.dev.vars\n.DS_Store\n",
  "AGENTS.md": "<!-- Generated by @omniharmonic/openspace-site-kit from the schema and block registry. Do not edit by hand; run `npx openspace agents-md` to refresh. -->\n# AGENTS.md — this OpenSpace site\n\nThis repository is an OpenSpace website. The content and design choices live here; the code\nlives in versioned npm packages (`@omniharmonic/openspace-site-kit`). Publishing happens automatically when\nchanges land on `main` (`.github/workflows/publish.yml`).\n\n## Rules\n\n1. **Content lives in `content/`.** Never hand-edit `src/`, `astro.config.mjs` or the\n   workflow unless you were asked for a custom block (`src/overrides/`).\n2. **Preserve ids.** Every page (`pg_`), section (`sec_`), block (`blk_`), media item (`med_`)\n   and form (`frm_`) has a stable id. Keep ids when editing; new ids are the prefix plus 10\n   lowercase Crockford base32 characters (no i, l, o, u).\n3. **Only valid block types and fields** (listed below; full JSON Schema at\n   https://schema.openspace.host/v1/). Unknown fields fail the build.\n4. **Styles change through tokens** in `content/styles.json` (palette, type pairing, density,\n   shape…), never inline CSS. Sections pick one of five color themes.\n5. **Never put secrets in content** (API keys, tokens, passwords). `openspace check` fails on them.\n   Members-only and password pages are only stubs here (a page file with `contentRef` and no\n   sections): their content is kept by the OpenSpace Hub and never committed. Edit them in\n   Studio or with the Hub's MCP tools; never add sections to a stub (they would be public).\n6. **Run `npx openspace check` before committing.** It validates schemas, links, image references,\n   size budgets and scans for secrets.\n7. Write real copy in the owner's voice. No placeholder text, no invented testimonials, prices\n   or facts — ask the owner.\n\n## Layout\n\n```\nopenspace.json               site id, Hub URL, deploy target, features (https://schema.openspace.host/v1/site-config.json)\ncontent/site.json            title, navigation, header, footer, SEO defaults, redirects\ncontent/styles.json          design tokens and Site Styles choices\ncontent/media.json           metadata for files in media/ (alt text, size, focal point, credit)\ncontent/pages/home.json      the home page (slug \"\"); other pages mirror their URL:\ncontent/pages/about.json     → /about/      content/pages/services/pricing.json → /services/pricing/\ncontent/collections/<name>/_collection.json   collection kind, list + item page layout, feeds\ncontent/collections/<name>/<slug>.mdoc        one item: YAML frontmatter + Markdoc body\nmedia/                       images ≤ 2400px on the long edge, audio, files\n```\n\nA page is `{ id, title, slug, seo?, sections: [...] }`; a section has a `layout` (`stack` with\ncolumn spans that add up to 12, or `grid`) and `blocks`; a block is\n`{ id, type, v, fields, variant?, style? }`.\n\n## Collection items (Markdoc)\n\nFrontmatter follows the collection kind (blog, events, portfolio, podcast, products): `title`,\n`status` (draft | scheduled | published), `publishAt` for scheduled items, `excerpt`, `image`,\n`categories`, `tags`, plus kind-specific fields (`date`, `start`/`end`, `price` in minor units…).\n\nThe body is Markdown prose plus Markdoc tags. **Tags map 1:1 to blocks**: the tag name is the\nblock type, attributes are its fields, and content between the tags fills its text:\n\n```markdoc\n{% gallery layout=\"grid\" images=[\"media/2026/10/a.jpg\", \"media/2026/10/b.jpg\"] /%}\n\n{% button href=\"/schedule\" variant=\"primary\" %}See the schedule{% /button %}\n```\n\nNo scripts or raw HTML: anything interactive is a block.\n\n## Running locally\n\n- `npm install`, then `npm run dev` for a live preview.\n- `npx openspace mcp` starts the local MCP server so an AI assistant can edit through the same\n  structured operations as the Studio.\n- `npm run build` builds the site into `dist/` exactly as the publish workflow does.\n\n## Blocks\n\n### `accordion` — Accordion / FAQ\n\nExpandable questions and answers, with schema.org FAQPage markup. Use: FAQs, policies, class or service details — anything visitors scan for one answer. 4–10 items works best. Avoid: Hiding essential information (prices, hours) only inside an accordion; answers longer than a short paragraph or list.\n\n- Variants: `lines`, `cards`, `minimal`\n- Fields: `items: list of { question: text ≤ 160, answer: richText }`, `exclusive: boolean`, `openFirst: boolean`, `faqSchema: boolean`\n\n### `audio` — Audio / podcast episode\n\nPlays one audio file — a podcast episode, track, talk or guided practice — with its notes. Use: Episode pages, music and talks. Add listen links for the podcast apps the show is on. `minimal` is just the player and title. Avoid: Autoplay (never supported); audio without a written summary or transcript link for deaf visitors.\n\n- Variants: `episode`, `card`, `minimal`\n- Fields: `audio?: media`, `title: text ≤ 120`, `show?: text ≤ 80`, `episode?: number`, `date?: text ≤ 10`, `description?: text ≤ 600`, `cover?: image { src, alt }`, `links: list of { platform: \"apple\" | \"spotify\" | \"youtube\" | \"rss\" | \"other\", label?: text ≤ 40, link: link }`, `credit?: text ≤ 200`\n\n### `before-after` — Before / after\n\nCompares two matching images with a draggable divider: renovations, retouching, seasons. Use: When the difference between two shots of the same view is the point. Use images with identical framing and size. Avoid: Unrelated images; misleading edits; more than one or two per page.\n\n- Variants: `labels`, `minimal`\n- Fields: `before: image { src, alt }`, `after: image { src, alt }`, `beforeLabel: text ≤ 30`, `afterLabel: text ≤ 30`, `start: number`, `aspect: \"original\" | \"1:1\" | \"4:5\" | \"2:3\" | \"3:2\" | \"16:9\" | \"21:9\"`, `caption?: text ≤ 200`\n\n### `booking` — Booking\n\nLets visitors book an appointment through the owner's Cal.com or Calendly page. Use: Services, coaching, consultations and classes booked by time slot. The scheduler loads only after a click, so the page stays fast and private. `button` just links out. Avoid: Scheduling links the owner hasn't set up; more than one booking block per page.\n\n- Variants: `inline`, `split`, `button`\n- Fields: `url: text ≤ 300`, `provider: \"auto\" | \"cal\" | \"calendly\"`, `heading?: text ≤ 80`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `description?: text ≤ 300`, `buttonLabel: text ≤ 30`, `height: \"640\" | \"760\" | \"900\"`\n\n### `button` — Button\n\nA clear call to action linking to a page, booking tool, email or file. Use: Once per screenful for the main action. Add a second (secondary-style) action only when it's a genuine alternative. Avoid: Several primary buttons side by side; vague labels like 'Click here' or 'Learn more' without context.\n\n- Variants: `default`, `large`, `full-width`\n- Fields: `label: text ≤ 40`, `link: link`, `role: \"primary\" | \"secondary\" | \"tertiary\"`, `secondaryLabel?: text ≤ 40`, `secondaryLink?: link`, `note?: text ≤ 120`\n\n### `card` — Card\n\nOne self-contained item — a service, offer, event or article teaser — with an optional link. Use: Place 2–4 cards side by side in stack columns for services or offers. `overlay` sets text on the photo; `horizontal` suits wide columns. Avoid: Long body text (keep under ~40 words); different aspect ratios across cards in a row.\n\n- Variants: `stacked`, `horizontal`, `overlay`, `minimal`\n- Fields: `image?: image { src, alt }`, `aspect: \"original\" | \"1:1\" | \"4:5\" | \"2:3\" | \"3:2\" | \"16:9\" | \"21:9\"`, `icon?: \"check\" | \"star\" | \"heart\" | \"leaf\" | \"sprout\" | \"flower\" | \"sun\" | \"moon\" | \"sparkles\" | \"mountain\" | \"waves\" | \"map-pin\" | \"phone\" | \"mail\" | \"message-circle\" | \"clock\" | \"calendar\" | \"coffee\" | \"utensils\" | \"music\" | \"camera\" | \"palette\" | \"brush\" | \"book-open\" | \"graduation-cap\" | \"user\" | \"users\" | \"heart-handshake\" | \"home\" | \"shield-check\" | \"lock\" | \"award\" | \"target\" | \"lightbulb\" | \"zap\" | \"rocket\" | \"gift\" | \"shopping-bag\" | \"package\" | \"truck\" | \"recycle\" | \"globe\" | \"wifi\" | \"car\" | \"bike\" | \"dumbbell\" | \"accessibility\" | \"baby\" | \"dog\" | \"paw-print\" | \"scissors\" | \"wrench\" | \"arrow-right\" | \"minus\" | \"x\" | \"trending-up\" | \"layers\" | \"code\" | \"plug\" | \"headphones\" | \"briefcase\" | \"droplet\" | \"hammer\" | \"flame\" | \"ticket\" | \"mic\" | \"pen-tool\" | \"feather\" | \"chart-bar\" | \"timer\" | \"hand-heart\" | \"plane\" | \"bed\" | \"building\" | \"ruler\" | \"search\" | \"smartphone\" | \"cloud\" | \"repeat\" | \"percent\" | \"handshake\" | \"stethoscope\" | \"gauge\" | \"workflow\" | \"puzzle\" | \"wine\" | \"cake\" | \"tent\" | \"eye\" | \"image\" | \"file-text\" | \"video\" | \"key-round\"`, `eyebrow?: text ≤ 40`, `heading: text ≤ 90`, `body: richText`, `link?: link`, `linkLabel?: text ≤ 30`\n\n### `chart` — Chart\n\nShows a small set of numbers as a bar, column, line or pie chart. Use: Up to ~12 values that tell one story: results, survey answers, growth over time. `line` for change over time, `pie` for shares of a whole (2–6 slices). Avoid: Invented or unsourced figures; pies with many slices; charts that need more than one series.\n\n- Variants: `bar`, `column`, `line`, `pie`\n- Fields: `title: text ≤ 120`, `description?: text ≤ 240`, `rows: list of { label: text ≤ 40, value: number }`, `prefix?: text ≤ 4`, `suffix?: text ≤ 12`, `showValues: boolean`, `showTable: boolean`\n\n### `columns` — Columns\n\nParallel content in columns: a feature trio, numbered steps, or short offers. Use: When 2–4 items share the same shape. `steps` numbers them for a process; `cards` puts each on a surface. Avoid: Uneven text lengths across columns; more than four columns; long paragraphs.\n\n- Variants: `plain`, `cards`, `steps`\n- Fields: `items: list of { image?: image { src, alt }, heading: text ≤ 80, body: richText, link?: link, linkLabel?: text ≤ 30 }`, `columns: \"2\" | \"3\" | \"4\"`, `aspect: \"original\" | \"1:1\" | \"4:5\" | \"2:3\" | \"3:2\" | \"16:9\" | \"21:9\"`\n\n### `contact-info` — Contact details\n\nHow to reach or visit the business: address, phone, email. Use: Contact pages, footers and beside a map or form. `columns` lays the details side by side on wide screens. Avoid: Personal phone numbers or addresses the owner hasn't chosen to publish.\n\n- Variants: `card`, `list`, `columns`\n- Fields: `heading?: text ≤ 60`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `name?: text ≤ 80`, `address?: text ≤ 240`, `phone?: text ≤ 30`, `email?: text ≤ 120`, `directions: boolean`, `note?: text ≤ 200`\n\n### `countdown` — Countdown\n\nA live countdown to a moment: a launch, a sale ending, an event starting. Use: Time-bound announcements near a call to action. The exact date is always printed too, so it still works without JavaScript. Avoid: Fake urgency (timers that reset); countdowns to dates that have long passed.\n\n- Variants: `boxes`, `inline`, `large`\n- Fields: `heading?: text ≤ 80`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `target: text ≤ 32`, `showSeconds: boolean`, `doneMessage: text ≤ 160`, `buttonLabel?: text ≤ 30`, `link?: link`\n\n### `divider` — Divider with ornament\n\nA decorative separator: a small ornament or label between thin lines. Use: Between passages of long-form text, menus or story pages where a plain line feels too stark. One or two per page. Avoid: Separating every block; ornaments that clash with a minimal site style.\n\n- Variants: `lines`, `ornament`, `label`\n- Fields: `ornament: \"flourish\" | \"star\" | \"diamond\" | \"dots\" | \"leaf\" | \"wave\" | \"asterism\"`, `label?: text ≤ 40`, `length: \"short\" | \"half\" | \"full\"`, `color: color`\n\n### `donation` — Donation\n\nCollects donations: preset or custom amounts, one-time or monthly. Use: Non-profits, community projects and creators. Say concretely what a gift pays for. `link` mode points to an existing donation page (Open Collective, Stripe Payment Link…). Avoid: Amounts or causes the owner hasn't approved; promising tax deductibility without confirming it.\n\n- Variants: `card`, `inline`, `split`\n- Fields: `heading?: text ≤ 80`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `description?: text ≤ 400`, `mode: \"checkout\" | \"link\"`, `currency: \"USD\" | \"EUR\" | \"GBP\" | \"CAD\" | \"AUD\" | \"NZD\" | \"CHF\" | \"SEK\" | \"NOK\" | \"DKK\" | \"JPY\"`, `amounts: list of { amount: number }`, `allowCustom: boolean`, `frequency: \"both\" | \"once\" | \"monthly\"`, `buttonLabel: text ≤ 30`, `link?: link`, `note?: text ≤ 200`\n\n### `embed` — Embed / Code\n\nEmbeds third-party widgets (booking, surveys, tickets, playlists) by URL or HTML snippet. Use: Only when no dedicated block exists for the service. Avoid: Tracking scripts; snippets with secrets or API keys; embedding YouTube/Vimeo (use the video block) or maps (use the map block).\n\n- Variants: `plain`, `framed`\n- Fields: `embed: embed`, `title: text ≤ 120`, `aspect: \"auto\" | \"16:9\" | \"4:3\" | \"1:1\"`, `height: number`\n\n### `events` — Events\n\nShows events from the events collection: dates, times, places and a way to register. Use: Home, schedule and community pages. `calendar` shows month grids with an agenda below; `list` is the most scannable. Avoid: Typing events into text blocks (add them to the events collection so they stay in sync).\n\n- Variants: `list`, `cards`, `calendar`\n- Fields: `heading?: text ≤ 80`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `source: reference`, `showImage: boolean`, `showLocation: boolean`, `showExcerpt: boolean`, `registerLabel: text ≤ 30`, `emptyMessage: text ≤ 160`, `structuredData: boolean`\n\n### `form` — Form\n\nCollects enquiries, bookings requests, RSVPs or applications into the owner's Inbox. Use: Contact pages and anywhere visitors need to send structured details. Pair with a short text block explaining what happens next. Avoid: Long forms (keep under ~8 fields); asking for sensitive data; password or payment fields (not allowed — payments go through checkout).\n\n- Variants: `default`, `card`, `underline`\n- Fields: `form: form`\n\n### `gallery` — Gallery\n\nSeveral related photographs shown together. Use: Portfolios, spaces, events and products. `grid` for tidy sets, `masonry` and `strips` for mixed orientations, `carousel` for many images in little space, `slideshow` for one large image at a time. Avoid: Mixing unrelated photos; fewer than three images (use the image block); captions that repeat alt text.\n\n- Variants: `grid`, `carousel`, `masonry`, `slideshow`, `strips`\n- Fields: `images: list of { image: image { src, alt }, caption?: text ≤ 160, link?: link }`, `aspect: \"auto\" | \"original\" | \"1:1\" | \"4:5\" | \"2:3\" | \"3:2\" | \"16:9\" | \"21:9\"`, `columns: \"2\" | \"3\" | \"4\" | \"5\"`, `lightbox: boolean`, `showCaptions: boolean`\n\n### `heading` — Heading\n\nA section heading with optional eyebrow and supporting line. Use: To open a section or introduce a group of blocks. `rule` adds a short accent line above, `underline` a line below, `split` puts the subheading beside the heading on wide screens. Avoid: Using headings for emphasis inside body copy (use text); skipping levels (h2 → h4); more than one Heading 1 per page.\n\n- Variants: `plain`, `rule`, `underline`, `split`\n- Fields: `eyebrow?: text ≤ 60`, `text: text ≤ 160`, `level: \"h1\" | \"h2\" | \"h3\" | \"h4\"`, `size: \"auto\" | \"display\" | \"h1\" | \"h2\" | \"h3\" | \"h4\"`, `subheading?: text ≤ 280`\n\n### `hours` — Opening hours\n\nWhen a place is open, day by day. Use: Contact, visit and footer areas of shops, studios, cafés and offices. Pair with the contact card or map. Avoid: Hours the owner hasn't confirmed; using it for event times (use events).\n\n- Variants: `table`, `compact`, `card`\n- Fields: `heading?: text ≤ 60`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `rows: list of { day: \"mon\" | \"tue\" | \"wed\" | \"thu\" | \"fri\" | \"sat\" | \"sun\", opens?: text ≤ 5, closes?: text ≤ 5, closed: boolean }`, `note?: text ≤ 200`\n\n### `icon-list` — Icon list\n\nA scannable list of features, amenities, benefits or what's included. Use: Services and pricing pages, 'what to expect' sections. 3–8 items. Avoid: Using icons that don't match the meaning; paragraphs instead of one-line points.\n\n- Variants: `list`, `tiles`, `checklist`\n- Fields: `items: list of { icon: \"check\" | \"star\" | \"heart\" | \"leaf\" | \"sprout\" | \"flower\" | \"sun\" | \"moon\" | \"sparkles\" | \"mountain\" | \"waves\" | \"map-pin\" | \"phone\" | \"mail\" | \"message-circle\" | \"clock\" | \"calendar\" | \"coffee\" | \"utensils\" | \"music\" | \"camera\" | \"palette\" | \"brush\" | \"book-open\" | \"graduation-cap\" | \"user\" | \"users\" | \"heart-handshake\" | \"home\" | \"shield-check\" | \"lock\" | \"award\" | \"target\" | \"lightbulb\" | \"zap\" | \"rocket\" | \"gift\" | \"shopping-bag\" | \"package\" | \"truck\" | \"recycle\" | \"globe\" | \"wifi\" | \"car\" | \"bike\" | \"dumbbell\" | \"accessibility\" | \"baby\" | \"dog\" | \"paw-print\" | \"scissors\" | \"wrench\" | \"arrow-right\" | \"minus\" | \"x\" | \"trending-up\" | \"layers\" | \"code\" | \"plug\" | \"headphones\" | \"briefcase\" | \"droplet\" | \"hammer\" | \"flame\" | \"ticket\" | \"mic\" | \"pen-tool\" | \"feather\" | \"chart-bar\" | \"timer\" | \"hand-heart\" | \"plane\" | \"bed\" | \"building\" | \"ruler\" | \"search\" | \"smartphone\" | \"cloud\" | \"repeat\" | \"percent\" | \"handshake\" | \"stethoscope\" | \"gauge\" | \"workflow\" | \"puzzle\" | \"wine\" | \"cake\" | \"tent\" | \"eye\" | \"image\" | \"file-text\" | \"video\" | \"key-round\", title: text ≤ 60, text?: text ≤ 200 }`, `columns: \"1\" | \"2\" | \"3\" | \"4\"`\n\n### `image` — Image\n\nA single photograph or illustration. Use: To show the place, the people, the work or the product. Keep aspect ratios consistent within a section. `caption-overlay` suits atmospheric shots; `inset` frames an image on a soft surface. Avoid: Stock photos that don't depict the business; text baked into images; missing alt text.\n\n- Variants: `default`, `caption-overlay`, `inset`\n- Fields: `image: image { src, alt }`, `aspect: \"original\" | \"1:1\" | \"4:5\" | \"2:3\" | \"3:2\" | \"16:9\" | \"21:9\"`, `caption?: text ≤ 200`, `link?: link`, `lightbox: boolean`\n\n### `line` — Line\n\nA visual divider between pieces of content. Use: To separate groups inside a section, or as a short accent rule above a heading (`length: short`, color `accent`). Avoid: Lines between every block; using lines where whitespace or a section change would do.\n\n- Variants: `solid`, `dashed`, `dotted`, `fade`\n- Fields: `thickness: \"hairline\" | \"regular\" | \"bold\"`, `length: \"full\" | \"half\" | \"short\"`, `color: color`\n\n### `link-list` — Link list\n\nA link-in-bio list: a few large, tappable links under a photo and one-line bio. Use: On a dedicated links page shared from social profiles, or a compact 'start here' list. Put the most important link first and highlight at most one. Avoid: More than ~8 links; vague labels like 'Click here'; duplicating the main navigation.\n\n- Variants: `stacked`, `outline`, `cards`\n- Fields: `photo?: image { src, alt }`, `name?: text ≤ 60`, `bio?: text ≤ 200`, `links: list of { label: text ≤ 60, link: link, icon?: \"check\" | \"star\" | \"heart\" | \"leaf\" | \"sprout\" | \"flower\" | \"sun\" | \"moon\" | \"sparkles\" | \"mountain\" | \"waves\" | \"map-pin\" | \"phone\" | \"mail\" | \"message-circle\" | \"clock\" | \"calendar\" | \"coffee\" | \"utensils\" | \"music\" | \"camera\" | \"palette\" | \"brush\" | \"book-open\" | \"graduation-cap\" | \"user\" | \"users\" | \"heart-handshake\" | \"home\" | \"shield-check\" | \"lock\" | \"award\" | \"target\" | \"lightbulb\" | \"zap\" | \"rocket\" | \"gift\" | \"shopping-bag\" | \"package\" | \"truck\" | \"recycle\" | \"globe\" | \"wifi\" | \"car\" | \"bike\" | \"dumbbell\" | \"accessibility\" | \"baby\" | \"dog\" | \"paw-print\" | \"scissors\" | \"wrench\" | \"arrow-right\" | \"minus\" | \"x\" | \"trending-up\" | \"layers\" | \"code\" | \"plug\" | \"headphones\" | \"briefcase\" | \"droplet\" | \"hammer\" | \"flame\" | \"ticket\" | \"mic\" | \"pen-tool\" | \"feather\" | \"chart-bar\" | \"timer\" | \"hand-heart\" | \"plane\" | \"bed\" | \"building\" | \"ruler\" | \"search\" | \"smartphone\" | \"cloud\" | \"repeat\" | \"percent\" | \"handshake\" | \"stethoscope\" | \"gauge\" | \"workflow\" | \"puzzle\" | \"wine\" | \"cake\" | \"tent\" | \"eye\" | \"image\" | \"file-text\" | \"video\" | \"key-round\", highlight: boolean }`, `showSocial: boolean`\n\n### `logo-strip` — Logo strip\n\nLogos of publications, clients, partners or certifications. Use: Below a hero or near a call to action as social proof. 4–8 logos reads best. Avoid: Logos without permission or for relationships that don't exist; mixing press and clients in one strip.\n\n- Variants: `row`, `grid`, `marquee`\n- Fields: `label?: text ≤ 60`, `logos: list of { name: text ≤ 60, logo?: image { src, alt }, link?: link }`, `monochrome: boolean`\n\n### `map` — Map\n\nShows where a place is, with the address and a link to full maps. Use: Contact and visit pages for any business with a physical location. Set latitude/longitude precisely; add parking or access notes in details. Avoid: Guessing coordinates — ask the owner or geocode the exact address; maps for online-only businesses.\n\n- Variants: `card`, `plain`, `split`\n- Fields: `name?: text ≤ 80`, `address: text ≤ 200`, `latitude: number`, `longitude: number`, `zoom: number`, `details?: text ≤ 240`, `linkLabel: text ≤ 40`, `tileServer?: text ≤ 300`, `aspect: \"16:9\" | \"3:2\" | \"4:3\" | \"1:1\"`\n\n### `marquee` — Scrolling text\n\nA continuously scrolling line of short phrases, like a ticker or a shop-window band. Use: For energy between sections: offerings, places, a short slogan. 3–8 phrases of 1–3 words. `band` sets it on an accent strip. Avoid: Essential information (it moves and can be paused); long sentences; more than one per page. It never moves for visitors who prefer reduced motion.\n\n- Variants: `text`, `outline`, `band`\n- Fields: `items: list of { text: text ≤ 60 }`, `separator: \"star\" | \"dot\" | \"slash\" | \"dash\" | \"none\"`, `size: \"lead\" | \"h3\" | \"h2\" | \"display\"`, `speed: \"slow\" | \"medium\" | \"fast\"`\n\n### `member-login` — Member sign-in\n\nLets members sign in with an emailed link, or tells visitors that content is members-only. Use: On the members' sign-in page (`form`), at the top of a members-only page's public teaser (`gated`), or as a slim prompt (`banner`). Members need the Cloudflare hosting option. Avoid: Putting the members-only content itself on a public page; asking for passwords.\n\n- Variants: `form`, `gated`, `banner`\n- Fields: `heading?: text ≤ 80`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `description?: text ≤ 300`, `buttonLabel: text ≤ 30`, `successMessage: text ≤ 200`, `signInLink?: link`, `joinLabel?: text ≤ 40`, `joinLink?: link`\n\n### `newsletter` — Newsletter signup\n\nCollects email subscribers (double opt-in) for the owner's newsletter. Use: Footers, the end of blog posts, and dedicated 'stay in touch' sections. Say what subscribers get and how often. Avoid: Promising content or frequency the owner hasn't agreed to; more than one signup per page.\n\n- Variants: `inline`, `stacked`, `card`, `banner`\n- Fields: `heading?: text ≤ 80`, `description?: text ≤ 240`, `askName: boolean`, `placeholder: text ≤ 60`, `buttonLabel: text ≤ 30`, `successMessage: text ≤ 200`, `note?: text ≤ 160`\n\n### `pricing` — Pricing table\n\nCompares plans, packages or tiers with prices and what each includes. Use: Pricing, membership and service-package pages. 2–4 plans; mark at most one as featured. Keep inclusions parallel across plans. Avoid: Prices the owner hasn't confirmed; hidden fees; more than ~6 inclusions per plan; using it for a single product (use the product block).\n\n- Variants: `cards`, `columns`, `compact`\n- Fields: `plans: list of { name: text ≤ 60, price: text ≤ 24, period?: text ≤ 30, description?: text ≤ 200, features: list of { text: text ≤ 120 }, buttonLabel?: text ≤ 30, link?: link, featured: boolean, badge?: text ≤ 24, altPrice?: text ≤ 24, altPeriod?: text ≤ 30 }`, `note?: text ≤ 200`, `periodLabel?: text ≤ 20`, `altPeriodLabel?: text ≤ 20`, `altNote?: text ≤ 24`\n\n### `product` — Product\n\nSells one product from the shop: image, price, options and an Add to cart button. Use: Featuring a single product on a landing page or inside a story. The price shown comes from the catalog; checkout always re-reads prices on the server. Avoid: Products that don't exist in the shop collection; writing prices by hand in text blocks.\n\n- Variants: `card`, `split`, `minimal`\n- Fields: `product: reference`, `showDescription: boolean`, `quantity: boolean`, `buttonLabel: text ≤ 30`, `detailsLabel: text ≤ 30`\n\n### `quote` — Quote\n\nA short, memorable quotation set apart from body text. Use: To pause the reader between sections, or to open a page with an epigraph. `large` is a centred statement, `bar` sits inside reading text. Avoid: Customer reviews (use testimonial); misattributed or invented quotes; quotes longer than three sentences.\n\n- Variants: `classic`, `large`, `bar`\n- Fields: `quote: richText`, `attribution?: text ≤ 80`, `source?: text ≤ 120`\n\n### `quote-carousel` — Quote carousel\n\nSeveral short quotes from clients or reviews in a swipeable carousel. Use: Social proof when there are four or more good testimonials and little space. `slides` shows one large quote at a time, `cards` several side by side. Avoid: Invented or edited quotes; fewer than three quotes (use testimonial); quotes over three sentences.\n\n- Variants: `slides`, `cards`, `minimal`\n- Fields: `label: text ≤ 80`, `quotes: list of { quote: text ≤ 400, name: text ≤ 80, role?: text ≤ 100, photo?: image { src, alt } }`\n\n### `restaurant-menu` — Menu\n\nA restaurant, café or bar menu: sections of dishes with descriptions and prices. Use: Menu pages and hospitality sites. Keep descriptions to one line; mark dietary information accurately. `columns` sets sections side by side on wide screens. Avoid: Out-of-date prices; dietary claims the kitchen can't guarantee; using it for services (use the pricing table).\n\n- Variants: `classic`, `columns`, `minimal`\n- Fields: `sections: list of { title: text ≤ 60, note?: text ≤ 160, items: list of { name: text ≤ 80, description?: text ≤ 240, price?: text ≤ 24, dietary: list of { tag: \"v\" | \"vg\" | \"gf\" | \"df\" | \"n\" | \"spicy\" } } }`, `currency?: text ≤ 4`, `legend: boolean`, `footnote?: text ≤ 240`\n\n### `search` — Search\n\nOpens the site's built-in search (Pagefind), which indexes every published page. Use: Sites with a blog, events or many pages — on a resources page, a 404 page or at the top of the journal. `icon` fits tight spaces. Avoid: Small sites of a few pages, where navigation is enough.\n\n- Variants: `field`, `button`, `icon`\n- Fields: `placeholder: text ≤ 60`, `shortcutHint: boolean`\n\n### `shape` — Shape\n\nDecorative shapes (blob, arch, sparkle, squiggle…) in palette colors. Use: In grid sections, layered behind or beside images and text to add warmth and brand character. Keep to one or two per section. Avoid: Using shapes to carry meaning or text; bright shapes behind body text that hurt contrast.\n\n- Variants: `solid`, `outline`, `soft`\n- Fields: `shape: \"circle\" | \"ring\" | \"blob\" | \"arch\" | \"half-circle\" | \"pill\" | \"squircle\" | \"triangle\" | \"sparkle\" | \"star\" | \"flower\" | \"wave\"`, `color: color`, `size: \"sm\" | \"md\" | \"lg\" | \"fill\"`, `rotate: number`, `stretch: boolean`\n\n### `share-buttons` — Share buttons\n\nShare links for the page being viewed (blog posts, events, announcements). Use: At the end of articles and event pages. Avoid: Putting share buttons on every page; more than four or five networks.\n\n- Variants: `icons`, `labels`, `pills`\n- Fields: `label?: text ≤ 40`, `networks: list of { network: \"x\" | \"facebook\" | \"linkedin\" | \"bluesky\" | \"threads\" | \"pinterest\" | \"email\" }`\n\n### `social-feed` — Social feed\n\nA grid of recent posts from the owner's social profile, linking to each post. Use: Near the footer or on about pages to show everyday life. Posts are fetched at publish time with the owner's permission, so no third-party scripts load. Avoid: Embedding other people's posts; feeds as the main content of a page.\n\n- Variants: `grid`, `row`, `mosaic`\n- Fields: `heading?: text ≤ 80`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `network: \"instagram\" | \"bluesky\" | \"mastodon\" | \"pinterest\" | \"tiktok\" | \"youtube\"`, `handle: text ≤ 80`, `count: \"3\" | \"4\" | \"6\" | \"8\"`, `followLabel: text ≤ 40`, `posts: list of { image: image { src, alt }, url: link, caption?: text ≤ 200 }`\n\n### `social-links` — Social links\n\nLinks to the owner's social media and email. Use: Footers, contact and about pages. Prefer `source: site` so profiles stay in sync across the site. Avoid: Linking to inactive accounts; more than ~6 networks.\n\n- Variants: `icons`, `labels`, `pills`\n- Fields: `source: \"site\" | \"custom\"`, `profiles: list of { network: \"instagram\" | \"facebook\" | \"x\" | \"threads\" | \"bluesky\" | \"mastodon\" | \"linkedin\" | \"youtube\" | \"tiktok\" | \"pinterest\" | \"github\" | \"spotify\" | \"soundcloud\" | \"bandcamp\" | \"vimeo\" | \"behance\" | \"dribbble\" | \"substack\" | \"patreon\" | \"yelp\" | \"tripadvisor\" | \"email\" | \"website\", url: text ≤ 300 }`, `label?: text ≤ 60`\n\n### `spacer` — Spacer\n\nExtra vertical space between blocks, sized from the site's spacing scale. Use: Sparingly, to give a heading or image more air than the default block gap. Avoid: Stacking spacers; using spacers to fake section padding (adjust the section instead).\n\n- Variants: —\n- Fields: `height: \"xs\" | \"sm\" | \"md\" | \"lg\" | \"xl\" | \"2xl\" | \"3xl\"`, `mobileHeight?: \"xs\" | \"sm\" | \"md\" | \"lg\" | \"xl\" | \"2xl\" | \"3xl\"`\n\n### `stats` — Stats\n\nKey figures that make a claim concrete (members, years, ratings, outcomes). Use: On about, services and fundraising pages; 3–4 numbers read best. `large` gives each number its own row. Avoid: Invented, rounded-up or unverifiable figures; more than six stats; vanity numbers.\n\n- Variants: `row`, `cards`, `large`\n- Fields: `items: list of { value: text ≤ 16, label: text ≤ 80, detail?: text ≤ 140 }`\n\n### `summary` — Summary\n\nLists items from a collection (blog posts, events, projects, episodes, products) as cards. Use: On the home page and landing pages to surface fresh content: the latest 3 posts, featured projects, upcoming events. `wall` is a masonry of images for portfolios; `carousel` saves space. Avoid: Using it as the main collection page (the collection's own list page does that); mixing unrelated filters; more than ~12 items.\n\n- Variants: `grid`, `list`, `carousel`, `wall`\n- Fields: `heading?: text ≤ 80`, `headingLevel: \"h2\" | \"h3\" | \"h4\"`, `source: reference`, `columns: \"2\" | \"3\" | \"4\"`, `showImage: boolean`, `showDate: boolean`, `showExcerpt: boolean`, `showMeta: boolean`, `linkLabel?: text ≤ 30`, `link?: link`, `emptyMessage: text ≤ 160`\n\n### `table` — Comparison table\n\nCompares plans, packages, products or options feature by feature in a real, accessible table. Use: Under a pricing section (full plan comparison), for specs, or 'us vs. the usual way'. 2–4 columns and 4–12 rows read best; use 'yes'/'no' for checks and dashes, group rows to break long lists. Avoid: Layout tables; more than five columns (phones scroll sideways); claims about competitors the owner can't back up; comparisons with named rival brands.\n\n- Variants: `lines`, `striped`, `boxed`\n- Fields: `caption?: text ≤ 120`, `corner?: text ≤ 40`, `columns: list of { label: text ≤ 40, detail?: text ≤ 40, highlight: boolean }`, `rows: list of { label: text ≤ 80, group: boolean, cells: list of { value: text ≤ 60 } }`, `note?: text ≤ 200`\n\n### `tabs` — Tabs\n\nParallel pieces of content shown one at a time, switched by tabs. Use: Comparable options (class styles, service tiers, menus by meal) where visitors want one at a time. 2–5 tabs with short labels. Avoid: Content everyone needs to read (tabs hide it); long labels; sequences (use a timeline) or FAQs (use an accordion).\n\n- Variants: `underline`, `pills`, `vertical`\n- Fields: `label: text ≤ 80`, `items: list of { label: text ≤ 40, content: richText }`\n\n### `team` — Team\n\nIntroduces the people behind the business: staff, teachers, partners, a board. Use: About and team pages, and near services where visitors choose a person. `circles` suits large teams; `list` gives each bio more room. Avoid: People who haven't agreed to appear; stock photos presented as staff; bios over ~60 words.\n\n- Variants: `grid`, `list`, `circles`\n- Fields: `people: list of { name: text ≤ 80, role?: text ≤ 80, photo?: image { src, alt }, bio?: text ≤ 320, link?: link }`, `columns: \"2\" | \"3\" | \"4\"`\n\n### `testimonial` — Testimonial\n\nA short quote from a client or customer, attributed to a named person. Use: Social proof near a call to action or on a services page. Use three side by side (`card`) or one `large` testimonial as a section's centrepiece. Avoid: Inventing testimonials or ratings. Ask the owner for real quotes and permission to use names and photos.\n\n- Variants: `card`, `large`, `minimal`\n- Fields: `quote: richText`, `name: text ≤ 80`, `role?: text ≤ 100`, `photo?: image { src, alt }`, `rating?: number`\n\n### `text` — Text\n\nRunning text: headings, paragraphs, lists and pull quotes. Use: Any time words carry the section — introductions, stories, policies. Use `columns` for long reading text, `drop-cap` for editorial openings, `callout` for a note that must stand out. Avoid: Walls of text; more than one H1 per page; using bold paragraphs as fake headings. Use the button block for calls to action.\n\n- Variants: `default`, `columns`, `drop-cap`, `callout`\n- Fields: `content: richText`\n\n### `timeline` — Timeline\n\nA sequence of dated or numbered milestones. Use: Company or project history, a programme's weeks, a process from enquiry to delivery. `horizontal` suits 3–5 short steps. Avoid: Undated lists (use a list or columns); invented history; more than ~10 milestones.\n\n- Variants: `vertical`, `alternating`, `horizontal`\n- Fields: `items: list of { date: text ≤ 40, title: text ≤ 100, text?: text ≤ 400 }`\n\n### `video` — Video\n\nA video from YouTube, Vimeo or PeerTube, or an uploaded video file. Use: Walkthroughs, talks, trailers and atmosphere. The player loads only when a visitor presses play, so pages stay fast. Avoid: Autoplaying sound; background loops longer than ~20 seconds; using a video where a photo says the same thing.\n\n- Variants: `default`, `framed`, `cinematic`\n- Fields: `source: \"embed\" | \"file\"`, `url?: text ≤ 500`, `file?: media`, `title: text ≤ 120`, `poster?: image { src, alt }`, `caption?: text ≤ 200`, `aspect: \"16:9\" | \"21:9\" | \"4:3\" | \"1:1\" | \"9:16\"`, `background: boolean`\n",
  "astro.config.mjs": "// OpenSpace site shell. Site, base path, routes, images, feeds and publishing all come from\n// openspace.json and content/ via the site-kit integration — there is nothing to configure here.\nimport openspace from \"@omniharmonic/openspace-site-kit\";\nimport { defineConfig } from \"astro/config\";\n\nexport default defineConfig({\n  integrations: [openspace()],\n});\n",
  "package.json": "{\n  \"name\": \"openspace-site\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"astro dev\",\n    \"build\": \"astro build\",\n    \"preview\": \"astro preview\",\n    \"check\": \"openspace check\"\n  },\n  \"dependencies\": {\n    \"@omniharmonic/openspace-site-kit\": \"^0.1.0\",\n    \"astro\": \"^7.4.2\"\n  },\n  \"devDependencies\": {\n    \"@omniharmonic/openspace-cli\": \"^0.1.0\"\n  },\n  \"engines\": {\n    \"node\": \">=22.23.4\"\n  }\n}\n",
  "src/pages/[...slug].astro": "---\n// Every page, collection item, list page and the 404 page of the site, rendered by\n// @omniharmonic/openspace-site-kit from content/. Custom code belongs in src/overrides/ (Advanced).\nimport { renderPage, staticPaths } from \"@omniharmonic/openspace-site-kit/route\";\n\nexport const getStaticPaths = staticPaths;\n// biome-ignore lint/correctness/noUnusedVariables: used by the template below\nconst html = await renderPage(Astro.props);\n---\n<Fragment set:html={html} />\n",
  "tsconfig.json": "{\n  \"extends\": \"astro/tsconfigs/strict\",\n  \"include\": [\".astro/types.d.ts\", \"**/*\"],\n  \"exclude\": [\"dist\"]\n}\n"
};

/** The hosting-specific files per target. */
export const STARTER_HOSTING_FILES = {
  "github-pages": {
    ".github/workflows/publish.yml": "# .github/workflows/publish.yml (generated; managed by site-kit updates)\nname: Publish\non:\n  push: { branches: [main] }\n  workflow_dispatch:\npermissions: { contents: read, pages: write, id-token: write }\nconcurrency: { group: publish, cancel-in-progress: true }\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        # package.json keys the npm cache: Hub-created sites have no lockfile at first.\n        with: { node-version: 24, cache: npm, cache-dependency-path: package.json }\n      - uses: actions/cache@v6\n        with:\n          path: node_modules/.astro\n          key: os-assets-${{ hashFiles('media/**') }}\n          restore-keys: os-assets-\n      # Sites created by the Hub start without a lockfile.\n      - run: if [ -f package-lock.json ]; then npm ci; else npm install; fi\n      - run: npx openspace check --ci # schema, links, budgets, secret scan\n      - run: npm run build # astro build (+ pagefind, og images)\n        env:\n          OPENSPACE_TURNSTILE_SITE_KEY: ${{ vars.OPENSPACE_TURNSTILE_SITE_KEY }}\n          # Self-host the font pairing (downloaded once from Google Fonts during the build).\n          OPENSPACE_GOOGLE_FONTS: download\n          OPENSPACE_REMOTE_IMAGES: download\n      - uses: actions/upload-pages-artifact@v5\n        with: { path: dist }\n  deploy:\n    needs: build\n    runs-on: ubuntu-latest\n    environment: { name: github-pages, url: \"${{ steps.d.outputs.page_url }}\" }\n    steps:\n      - id: d\n        uses: actions/deploy-pages@v5\n",
    "astro.config.mjs": "// OpenSpace site shell. Site, base path, routes, images, feeds and publishing all come from\n// openspace.json and content/ via the site-kit integration — there is nothing to configure here.\nimport openspace from \"@omniharmonic/openspace-site-kit\";\nimport { defineConfig } from \"astro/config\";\n\nexport default defineConfig({\n  integrations: [openspace()],\n});\n"
  },
  "cloudflare": {
    ".github/workflows/publish.yml": "# .github/workflows/publish.yml (generated; managed by site-kit updates) — Cloudflare target.\n# Prerendered pages deploy as static assets of a Worker in the owner's Cloudflare account; the\n# Worker serves members pages, sign-in and password pages. The D1 database is provisioned\n# automatically on the first deploy. Members-only / password page content is never in this\n# repository: the Hub keeps it, and this run copies the versions its commit names into the\n# Worker's private R2 bucket (authorized by the run's GitHub OIDC identity, no stored token).\nname: Publish\non:\n  push: { branches: [main] }\n  workflow_dispatch:\npermissions: { contents: read }\nconcurrency: { group: publish, cancel-in-progress: true }\njobs:\n  # Members-only and password pages → the Worker's private R2 bucket (from the Hub). The only job\n  # that may mint the run's identity token, so it installs nothing: one Node script, built-ins only.\n  gated:\n    runs-on: ubuntu-latest\n    permissions: { contents: read, id-token: write }\n    steps:\n      - uses: actions/checkout@v7\n        with: { persist-credentials: false }\n      - uses: actions/setup-node@v7\n        with: { node-version: 24 }\n      - run: node .github/openspace/gated-sync.mjs\n        env:\n          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}\n          CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}\n  publish:\n    needs: gated\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        # package.json keys the npm cache: Hub-created sites have no lockfile at first.\n        with: { node-version: 24, cache: npm, cache-dependency-path: package.json }\n      - uses: actions/cache@v6\n        with:\n          path: node_modules/.astro\n          key: os-assets-${{ hashFiles('media/**') }}\n          restore-keys: os-assets-\n      # Sites created by the Hub start without a lockfile.\n      - run: if [ -f package-lock.json ]; then npm ci; else npm install; fi\n      - run: npx openspace check --ci # schema, links, budgets, secret scan\n      - run: npm run build # astro build (+ pagefind, og images, Worker)\n        env:\n          OPENSPACE_TURNSTILE_SITE_KEY: ${{ vars.OPENSPACE_TURNSTILE_SITE_KEY }}\n          # Self-host the font pairing (downloaded once from Google Fonts during the build).\n          OPENSPACE_GOOGLE_FONTS: download\n          OPENSPACE_REMOTE_IMAGES: download\n      # Worker secrets from this repository's Actions secrets (the Hub sets them): the member\n      # session key, page password hashes and, in sovereign mode, the owner's own Stripe keys.\n      # Before the deploy, so the new version starts with them: on the very first run\n      # `wrangler secret bulk` creates the Worker as a draft (non-interactive default), and\n      # `wrangler deploy` never deletes secrets. Re-running is idempotent.\n      - name: Worker secrets\n        env:\n          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}\n          CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}\n          OS_SESSION_SECRET: ${{ secrets.OS_SESSION_SECRET }}\n          OS_PAGE_PASSWORDS: ${{ secrets.OS_PAGE_PASSWORDS }}\n          STRIPE_SECRET_KEY: ${{ secrets.STRIPE_SECRET_KEY }}\n          STRIPE_WEBHOOK_SECRET: ${{ secrets.STRIPE_WEBHOOK_SECRET }}\n        run: |\n          node -e 'const o={};for(const k of [\"OS_SESSION_SECRET\",\"OS_PAGE_PASSWORDS\",\"STRIPE_SECRET_KEY\",\"STRIPE_WEBHOOK_SECRET\"])if(process.env[k])o[k]=process.env[k];if(Object.keys(o).length)require(\"fs\").writeFileSync(process.env.RUNNER_TEMP+\"/os-secrets.json\",JSON.stringify(o),{mode:0o600})'\n          if [ -f \"$RUNNER_TEMP/os-secrets.json\" ]; then npx wrangler secret bulk \"$RUNNER_TEMP/os-secrets.json\"; fi\n          rm -f \"$RUNNER_TEMP/os-secrets.json\"\n      - run: npx wrangler deploy\n        env:\n          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}\n          CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}\n",
    "astro.config.mjs": "// OpenSpace site shell — Cloudflare target. Pages are prerendered as static assets; the Worker\n// serves members pages, sign-in and password pages. Everything else comes from openspace.json\n// and content/ via the site-kit integration.\nimport cloudflare from \"@astrojs/cloudflare\";\nimport openspace, { CLOUDFLARE_ADAPTER_OPTIONS } from \"@omniharmonic/openspace-site-kit\";\nimport { defineConfig } from \"astro/config\";\n\nexport default defineConfig({\n  adapter: cloudflare(CLOUDFLARE_ADAPTER_OPTIONS),\n  integrations: [openspace()],\n});\n",
    "wrangler.jsonc": "{\n  \"$schema\": \"./node_modules/wrangler/config-schema.json\",\n  // Renamed to the site's repository name when Cloudflare hosting is connected.\n  \"name\": \"openspace-site\",\n  \"compatibility_date\": \"2026-10-01\",\n  \"compatibility_flags\": [\"nodejs_compat\"],\n  // Gated (members / password) page content — never stored in the public repository. The\n  // publish workflow (`openspace gated-sync`) creates the bucket and fills it from the Hub.\n  \"r2_buckets\": [{ \"binding\": \"OS_GATED\", \"bucket_name\": \"openspace-site-gated\" }],\n  // Stock and orders for the store (Phase 5).\n  \"d1_databases\": [{ \"binding\": \"OS_DB\" }],\n  \"observability\": { \"enabled\": true }\n}\n",
    ".github/openspace/gated-sync.mjs": "// Members-only and password pages → the Worker's private R2 bucket (generated; managed by\n// site-kit updates). Runs in the publish workflow's `gated` job — the only job allowed to mint\n// the run's GitHub OIDC identity token — with no packages installed: Node built-ins only.\n//\n// The committed page files are stubs (`contentRef`, no sections); the OpenSpace Hub keeps their\n// content. This asks the Hub for exactly the versions this commit names and puts them at\n// `pages/<pageId>/<contentRef>.json` through the Cloudflare API, before the Worker deploys.\nimport { readdir, readFile } from \"node:fs/promises\";\nimport { join } from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\n\nconst CF_API = \"https://api.cloudflare.com/client/v4\";\n\nasync function pageFiles(dir) {\n  let entries = [];\n  try {\n    entries = await readdir(dir, { withFileTypes: true });\n  } catch {\n    return [];\n  }\n  const out = [];\n  for (const e of entries) {\n    const p = join(dir, e.name);\n    if (e.isDirectory()) out.push(...(await pageFiles(p)));\n    else if (e.name.endsWith(\".json\")) out.push(p);\n  }\n  return out;\n}\n\n/** The OS_GATED bucket name from wrangler.jsonc (line comments and trailing commas allowed). */\nfunction bucketName(text) {\n  const json = text\n    .replace(/\\/\\*[\\s\\S]*?\\*\\//g, \"\")\n    .replace(/^\\s*\\/\\/.*$/gm, \"\")\n    .replace(/,(\\s*[}\\]])/g, \"$1\");\n  return JSON.parse(json).r2_buckets?.find((b) => b.binding === \"OS_GATED\")?.bucket_name;\n}\n\n/** The Hub must be https (plain http only for a local Hub). */\nfunction hubOrigin(raw) {\n  const url = new URL(String(raw));\n  const local = [\"localhost\", \"127.0.0.1\", \"[::1]\"].includes(url.hostname);\n  if (url.protocol !== \"https:\" && !(url.protocol === \"http:\" && local))\n    throw new Error(`The Hub address must use https (got ${url.origin}).`);\n  return String(raw).replace(/\\/+$/, \"\");\n}\n\nexport async function main({\n  cwd = process.cwd(),\n  env = process.env,\n  fetch = globalThis.fetch,\n  log = console.log,\n} = {}) {\n  const config = JSON.parse(await readFile(join(cwd, \"openspace.json\"), \"utf8\"));\n  const stubs = [];\n  for (const file of await pageFiles(join(cwd, \"content/pages\"))) {\n    const page = JSON.parse(await readFile(file, \"utf8\"));\n    if (typeof page.id === \"string\" && typeof page.contentRef === \"string\")\n      stubs.push({ id: page.id, ref: page.contentRef });\n  }\n  if (!stubs.length) {\n    log(\"No members-only or password pages to upload.\");\n    return 0;\n  }\n  const hub = hubOrigin(config.hub);\n  const bucket = bucketName(await readFile(join(cwd, \"wrangler.jsonc\"), \"utf8\"));\n  if (!bucket) throw new Error('wrangler.jsonc has no \"bucket_name\" for the OS_GATED binding.');\n  const { CLOUDFLARE_API_TOKEN: cfToken, CLOUDFLARE_ACCOUNT_ID: account } = env;\n  if (!cfToken || !account)\n    throw new Error(\"CLOUDFLARE_API_TOKEN and CLOUDFLARE_ACCOUNT_ID are needed.\");\n  if (!env.ACTIONS_ID_TOKEN_REQUEST_URL || !env.ACTIONS_ID_TOKEN_REQUEST_TOKEN)\n    throw new Error(\"This job needs `permissions: id-token: write`.\");\n  const tokenUrl = new URL(env.ACTIONS_ID_TOKEN_REQUEST_URL);\n  tokenUrl.searchParams.set(\"audience\", hub);\n  const idRes = await fetch(tokenUrl.toString(), {\n    headers: { authorization: `Bearer ${env.ACTIONS_ID_TOKEN_REQUEST_TOKEN}` },\n  });\n  const idToken = idRes.ok ? (await idRes.json()).value : undefined;\n  if (!idToken) throw new Error(`GitHub didn't issue an identity token (${idRes.status}).`);\n  const res = await fetch(`${hub}/ci/sites/${encodeURIComponent(config.siteId)}/gated`, {\n    headers: { authorization: `Bearer ${idToken}`, accept: \"application/json\" },\n  });\n  const body = await res.json().catch(() => ({}));\n  if (!res.ok || !Array.isArray(body.pages))\n    throw new Error(\n      `The Hub didn't hand over the private pages (${res.status} ${body.error?.message ?? \"\"}).`,\n    );\n  const byKey = new Map(body.pages.map((p) => [`${p.id}/${p.ref}`, p]));\n  const missing = stubs.filter((s) => !byKey.has(`${s.id}/${s.ref}`));\n  if (missing.length)\n    throw new Error(`Missing private page content: ${missing.map((m) => m.id).join(\", \")}.`);\n  const cf = (path, init = {}) =>\n    fetch(`${CF_API}/accounts/${account}${path}`, {\n      ...init,\n      headers: { authorization: `Bearer ${cfToken}`, ...init.headers },\n    });\n  // Create the bucket on the first run (an existing bucket answers 409).\n  const created = await cf(\"/r2/buckets\", {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\" },\n    body: JSON.stringify({ name: bucket }),\n  });\n  if (!created.ok && created.status !== 409)\n    throw new Error(`Creating ${bucket} failed (${created.status}).`);\n  for (const s of stubs) {\n    const put = await cf(`/r2/buckets/${bucket}/objects/pages/${s.id}/${s.ref}.json`, {\n      method: \"PUT\",\n      headers: { \"content-type\": \"application/json\" },\n      body: JSON.stringify(byKey.get(`${s.id}/${s.ref}`).page),\n    });\n    if (!put.ok) throw new Error(`Uploading ${s.id} failed (${put.status}).`);\n  }\n  log(`Uploaded ${stubs.length} private page(s) to ${bucket}.`);\n  return stubs.length;\n}\n\nif (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href)\n  main().catch((err) => {\n    console.error(`::error::${err.message}`);\n    process.exit(1);\n  });\n"
  }
} as const;

/** package.json entries the Cloudflare variant adds to the shell's (merged, never overwritten). */
export const CLOUDFLARE_PACKAGE_ADDITIONS: Record<string, Record<string, string>> = {
  "dependencies": {
    "@astrojs/cloudflare": "^14.4.2"
  },
  "devDependencies": {
    "wrangler": "^4.152.0"
  }
};
